@staticmethod
def encode_composite_pk(pk_field, obj):
    """
    Encode a composite primary key as a JSON array string, using the
    declaration order of the key's fields. Each element is converted with
    the corresponding component field's to_python(), so an integer can
    never be confused with its digit string and None can never be
    confused with the string "None".
    """
    values = [
        None if value is None else field.to_python(value)
        for field, value in zip(pk_field.fields, obj.pk)
    ]
    try:
        return json.dumps(values, ensure_ascii=False)
    except (TypeError, ValueError) as exc:
        raise ValueError("Composite primary key has an unencodable component.") from exc

